import{bV as d,aL as e,u as a,G as o}from"./chunks/framework.DvBUyM1S.js";const m=JSON.parse('{"title":"免费大模型 API 平台选型清单（2026-09）","description":"","frontmatter":{"id":"PB-20260903-001","type":"playbook","title":"免费大模型 API 平台选型清单（2026-09）","tags":["free-api","llm","platform-selection","quota"],"status":"draft","source":"web-collected:2026-09-03","created":"2026-09-03T00:00:00.000Z","updated":"2026-09-03T00:00:00.000Z"},"headers":[],"relativePath":"playbooks/free-llm-api-platforms.md","filePath":"playbooks/free-llm-api-platforms.md"}'),r={name:"playbooks/free-llm-api-platforms.md"};function l(s,t,i,n,h,c){return e(),a("div",null,[...t[0]||(t[0]=[o('<h1 id="免费大模型-api-平台选型清单-2026-09" tabindex="-1">免费大模型 API 平台选型清单（2026-09） <a class="header-anchor" href="#免费大模型-api-平台选型清单-2026-09" aria-label="Permalink to &quot;免费大模型 API 平台选型清单（2026-09）&quot;">​</a></h1><blockquote><p>来源：2026-08 ~ 2026-09 全网检索（官方文档核实版博客园文、CSDN 限额实测、Agnes 官方站与智源社区报道、国内云厂商额度汇总）。 免费政策变动极快，<strong>动手前先花一分钟核对官方「价格 / 额度」页</strong>。</p></blockquote><h2 id="_1-先分清三种「免费」" tabindex="-1">1. 先分清三种「免费」 <a class="header-anchor" href="#_1-先分清三种「免费」" aria-label="Permalink to &quot;1. 先分清三种「免费」&quot;">​</a></h2><table tabindex="0"><thead><tr><th>类型</th><th>特征</th><th>典型</th><th>适合</th></tr></thead><tbody><tr><td>永久免费模型</td><td>指定模型无期限免费调用，通常限速</td><td>智谱 Flash 系列、Agnes 全模态</td><td>长期原型、Agent 日常</td></tr><tr><td>新用户赠送额度</td><td>一次性 token 包，有有效期</td><td>阿里百炼、腾讯混元、百度千帆</td><td>短期验证、压测</td></tr><tr><td>海外免费层</td><td>限速不限量，随时可调</td><td>Google AI Studio、Groq、Cerebras</td><td>学习实验（需代理）</td></tr></tbody></table><p>判断标准：官方定价页是否<strong>明确标注 Free</strong>，而非「赠送 XX 万 token」。查不到的数字一律以控制台实际显示为准。</p><h2 id="_2-国内直连-无需代理" tabindex="-1">2. 国内直连（无需代理） <a class="header-anchor" href="#_2-国内直连-无需代理" aria-label="Permalink to &quot;2. 国内直连（无需代理）&quot;">​</a></h2><table tabindex="0"><thead><tr><th>平台</th><th>免费内容</th><th>门槛 / 有效期</th><th>备注</th></tr></thead><tbody><tr><td>智谱开放平台</td><td>8 款 Flash 模型明确标「免费」：GLM-4.7-Flash(200K)、GLM-4-Flash-250414(128K)、GLM-4.5-Flash(128K，即将下线)、GLM-4.6V-Flash、GLM-4.1V-Thinking-Flash、GLM-4V-Flash、CogView-3-Flash、CogVideoX-Flash(4K/60fps,10s)</td><td>手机号，免信用卡，长期</td><td>兼容 OpenAI 格式，<strong>国内起步首选</strong>；仍有速率/额度限制</td></tr><tr><td>硅基流动 SiliconFlow</td><td>指定开源模型免费（如 Qwen2.5-7B）</td><td>手机号</td><td>一个 Key 切多家开源模型，适合对比测试</td></tr><tr><td>Agnes AI（国内站）</td><td>全模态三剑客无限期免费：文本 <code>agnes-2.0-flash</code> / <code>agnes-2.5-flash</code>、图像 <code>agnes-image-2.1-flash</code>(4K)、视频 <code>agnes-video-v2.0</code>；文本 1M 上下文</td><td>邮箱注册，不绑卡</td><td>2026-07-29 入口迁至 .cn，旧 Key 有效，改 base_url 即可</td></tr><tr><td>阿里云百炼</td><td>新用户每模型约 100 万 token，覆盖 70+ 模型，累计约 7000 万</td><td>需华北 2（北京）地域，90 天有效</td><td>只能抵扣实时调用，批量/调优不适用</td></tr><tr><td>腾讯混元</td><td>通用包 100 万 token 多模型共享 + 100 万 Embedding；Hunyuan-lite 永久免费(256K)</td><td>有效期 1 年</td><td>微信生态/小程序接入最顺</td></tr><tr><td>百度千帆</td><td>每模型独立送 100 万 token，ERNIE-4.5 系列适用</td><td>多数 3 个月</td><td>并发限制较宽松，适合压测</td></tr><tr><td>字节火山方舟</td><td>新用户赠送额度（各模型独立）</td><td>有效期短</td><td>见控制台</td></tr><tr><td>DeepSeek</td><td>无永久免费模型，但有赠送余额机制；v4-flash 输入 1 元/百万 token、输出 2 元</td><td>峰谷定价，空闲约五折</td><td>中文/代码/推理首选，充 5 元能用很久</td></tr><tr><td>小米 MiMo</td><td>MiMo Orbit 100T 计划，申请制，通过后可达亿级 token</td><td>30 天有效，发完即止</td><td>需写使用场景申请，配合 cc-switch 接入</td></tr><tr><td>七牛云 AI</td><td>新用户赠 300 万 token</td><td>见官网</td><td>聚合多模型，按 token 计费</td></tr></tbody></table><h2 id="_3-海外-需代理" tabindex="-1">3. 海外（需代理） <a class="header-anchor" href="#_3-海外-需代理" aria-label="Permalink to &quot;3. 海外（需代理）&quot;">​</a></h2><table tabindex="0"><thead><tr><th>平台</th><th>免费额度规则</th><th>代表模型</th></tr></thead><tbody><tr><td>Google AI Studio</td><td>因模型而异：Gemini Flash 约 20 请求/天，Gemma 3 系列可达 14400 请求/天</td><td>Gemini 2.5/3、Gemma 3</td></tr><tr><td>Groq</td><td>因模型而异，Llama 3.1 8B 最高 14400 请求/天</td><td>Llama、Whisper、Qwen3</td></tr><tr><td>Cerebras</td><td>30 请求/分钟，100 万 token/天</td><td>gpt-oss-120b、Llama 3.1 8B</td></tr><tr><td>OpenRouter</td><td>未充值：20 RPM / 50 RPD；充值满 $10：20 RPM / 1000 RPD（<code>:free</code> 后缀模型）</td><td>Llama 3.3 70B、gpt-oss-120b、Qwen3 Coder</td></tr><tr><td>Cloudflare Workers AI</td><td>每天 10000 neurons</td><td>Llama、Gemma、Qwen、GLM、Kimi</td></tr><tr><td>HuggingFace Inference</td><td>每月 $0.10 额度，限 10GB 以下模型</td><td>各类开源小模型</td></tr><tr><td>NVIDIA NIM</td><td>40 请求/分钟，需手机号验证</td><td>多款开源模型</td></tr></tbody></table><h2 id="_4-agnes-接入要点-踩坑已验证" tabindex="-1">4. Agnes 接入要点（踩坑已验证） <a class="header-anchor" href="#_4-agnes-接入要点-踩坑已验证" aria-label="Permalink to &quot;4. Agnes 接入要点（踩坑已验证）&quot;">​</a></h2><ul><li>国内站：<code>https://agnes-ai.cn/</code>，Key 在 <code>https://platform.agnes-ai.cn/settings/apiKeys</code>，文档 <code>https://agnes-ai.cn/zh-Hans/docs/overview</code>。</li><li>兼容 OpenAI 格式，接 Claude Code / Codex / OpenClaw / Trae 只需自定义 provider + base_url + 模型名。</li><li>模型名坑：<code>agnes-image-2.0-flash</code> 实测稳定 503，<code>/v1/models</code> 里只有 <code>agnes-image-2.1-flash</code>。</li><li>生图请求<strong>不要带 <code>response_format</code></strong>，带顶层该参数直接 400；最简请求 = <code>model + prompt + size</code>，默认返回 url。</li><li>内容审核严格：武器类词（剑/武侠）+ hyper-realistic 会触发 <code>content_policy_violation</code>，改写为艺术化描述后通过。</li><li>视频结果 URL 在<strong>顶层 <code>url</code> 字段</strong>（不是 metadata.url）；尺寸会被归一化到标准档；<code>num_frames</code> 最多 441（约 18 秒）。</li><li>文档里部分地址仍是国际版 <code>.com</code>，调用时注意 base_url 的 .com / .cn 区分。</li></ul><h2 id="_5-选型速查" tabindex="-1">5. 选型速查 <a class="header-anchor" href="#_5-选型速查" aria-label="Permalink to &quot;5. 选型速查&quot;">​</a></h2><table tabindex="0"><thead><tr><th>需求</th><th>首选</th><th>备选</th></tr></thead><tbody><tr><td>中文对话/工具调用/零成本跑通</td><td>智谱 GLM-4.7-Flash</td><td>硅基流动免费模型</td></tr><tr><td>代码 / 数学 / 推理</td><td>DeepSeek v4-flash（便宜）</td><td>Agnes 2.5-flash（免费 + 1M 上下文）</td></tr><tr><td>全模态（图 + 视频）零成本</td><td>Agnes</td><td>智谱 CogView / CogVideo Flash</td></tr><tr><td>多模型对比</td><td>硅基流动 / OpenRouter <code>:free</code></td><td>—</td></tr><tr><td>极速响应</td><td>Groq</td><td>智谱 Flash</td></tr><tr><td>长文档</td><td>Gemini Flash（代理）/ Agnes 1M</td><td>Kimi（直连）</td></tr></tbody></table><h2 id="_6-通用踩坑" tabindex="-1">6. 通用踩坑 <a class="header-anchor" href="#_6-通用踩坑" aria-label="Permalink to &quot;6. 通用踩坑&quot;">​</a></h2><ol><li><strong>多账号刷额度无效</strong>：OpenRouter 等平台的限流是全局的，多 Key 不叠加。</li><li><strong>429 不一定是限流</strong>：可能是上游容量不足，实现指数退避并读 <code>Retry-After</code>。</li><li><strong>数据协议</strong>：Mistral 免费层要求同意数据用于训练，敏感项目避开。</li><li><strong>免费模型随时下线</strong>：GLM-4.5-Flash 官方已标注「即将下线」，长期项目别只押一条。</li><li><strong>别拿免费层扛生产流量</strong>：20~30 RPM 撑不住真实并发。</li><li><strong>警惕影子 API</strong>：第三方「免费 GPT-5/o3/Grok」中转实测正确率可从 83% 掉到 37%，只走官方免费层。</li></ol><h2 id="_7-起步路径-15-分钟" tabindex="-1">7. 起步路径（15 分钟） <a class="header-anchor" href="#_7-起步路径-15-分钟" aria-label="Permalink to &quot;7. 起步路径（15 分钟）&quot;">​</a></h2><ol><li>手机号注册智谱 → 建 API Key → 调 <code>GLM-4.7-Flash</code>（OpenAI 格式，国内直连）。</li><li>邮箱注册 Agnes 国内站 → 建 Key → 补上全模态（图/视频/1M 文本）。</li><li>需要更强代码推理时，DeepSeek 充 5~10 元用 v4-flash。</li></ol>',17)])])}const p=d(r,[["render",l]]);export{m as __pageData,p as default};
